"""Imports a model generated by Hyper3D Rodin, scales and orients it like Noah's turnaround sheet,
and renders it from the same 4 views to compare them.

Live usage (with Blender open):
    python3 tools/blender/live.py rodin "step_import('/path/model.glb')" "step_render('/folder')"
"""

import math
import os

import bpy
from mathutils import Vector

ROOT = globals().get("PROJECT_ROOT", os.getcwd())
# Reuses the lights, cameras and scale from noah_data.py (without running its main).
_ns = {"LIVE": True, "PROJECT_ROOT": ROOT, "__name__": "noah_data"}
exec(open(os.path.join(ROOT, "tools/blender/noah_data.py"), encoding="utf-8").read(), _ns)
step_render = _ns["step_render"]
HEIGHT = 1.55


def step_import(path, yaw_deg=0.0):
    for o in list(bpy.data.objects):
        bpy.data.objects.remove(o)
    before = set(bpy.data.objects)
    bpy.ops.import_scene.gltf(filepath=path)
    new = [o for o in bpy.data.objects if o not in before]
    meshes = [o for o in new if o.type == "MESH"]
    root = bpy.data.objects.new("Rodin", None)
    bpy.context.scene.collection.objects.link(root)
    for o in new:
        if o.parent is None:
            o.parent = root
    bpy.context.view_layer.update()
    pts = [o.matrix_world @ Vector(c) for o in meshes for c in o.bound_box]
    lo = Vector((min(p.x for p in pts), min(p.y for p in pts), min(p.z for p in pts)))
    hi = Vector((max(p.x for p in pts), max(p.y for p in pts), max(p.z for p in pts)))
    scale = HEIGHT / (hi.z - lo.z)
    root.scale = (scale, scale, scale)
    root.location = (-(lo.x + hi.x) / 2 * scale, -(lo.y + hi.y) / 2 * scale, -lo.z * scale)
    # Rotates around the vertical axis through the center.
    bpy.context.view_layer.update()
    pivot = bpy.data.objects.new("RodinTurn", None)
    bpy.context.scene.collection.objects.link(pivot)
    root.parent = pivot
    pivot.rotation_euler = (0, 0, math.radians(yaw_deg))
    print("imported", len(meshes), "meshes, scale", round(scale, 4), "original size", [round(v, 3) for v in (hi - lo)])


def step_turn(yaw_deg):
    bpy.data.objects["RodinTurn"].rotation_euler = (0, 0, math.radians(yaw_deg))
